sys_script_client.script:
function onLoad() {
    if ((g_form.getValue('trade_task_type') != 'Maker') && (g_form.getValue('state') != 1 || g_form.getValue('state') != 2)) {
        return;
    }
    var userHasRole = g_user.hasRole('x_hsb11_mss_c_proc.DCCAUCSTUser'); //added as part of MSSCUSTODY-7081 & MSSCUSTODY-8054
    var taskShortDesc = g_form.getValue('short_description'); //added as part of MSSCUSTODY-7081 & MSSCUSTODY-8054
    if (g_scratchpad.isCstTask) { //added as part of MSSCUSTODY-7081 & MSSCUSTODY-8054
        g_form.clearOptions('outcome');
        g_form.addOption('outcome', '', '-- None --');
        if (taskShortDesc.indexOf('NEWM') > -1) {
            g_form.addOption('outcome', 'Rejected NEWM SWIFT to Not be Processed', 'Rejected Swift - No Action Required');
        } else if (taskShortDesc.indexOf('CANC') > -1) {
            g_form.addOption('outcome', 'Rejected SWIFT CANC to Not Be Processed', 'Rejected Swift - No Action Required');

        }
        return;
    } //added as part of MSSCUSTODY-7081 & MSSCUSTODY-8054

    var existingValue = g_form.getValue('outcome');
    var templateId = g_form.getValue('trade_task_template_id');
    var tradeID = g_form.getValue('trade_id');

    g_form.clearOptions('outcome');
    g_form.addOption('outcome', '', '-- None --');

    var ga = new GlideAjax('HSBCTradeTaskUtils');
    ga.addParam('sysparm_name', 'getOutcomesOptions');
    ga.addParam('sysparm_template_id', templateId);
    ga.addParam('sysparm_trade_id', tradeID);
    ga.addParam('sysparm_task_number', g_form.getValue('number'));
    ga.getXMLAnswer(function(response) {
        outcomesParse(response);

        // For Workspace
        if (typeof(g_aw) != 'undefined') {
            g_form.addOption('outcome', existingValue, existingValue);
        } else {
            // for Classic
            g_form.setValue('outcome', existingValue);
        }

        // Amend-based maker outcome
        if (g_scratchpad.multipleMaker.toString() == 'true') {
            g_form.removeOption('outcome', 'Review and closed the task');
            g_form.addOption('outcome', 'Review and closed the task', 'Review and close the task');
        }

        // var legacyStatus = g_scratchpad.trdLifeCycle;
        // var legacySubStatus = g_scratchpad.trdSubStatus;
        // if (
        //     (legacyStatus != 'PAPP' && legacySubStatus != 'R&D Capture') ||
        //     legacyStatus != 'PRPR' ||
        //     legacyStatus != 'PCON'
        // ) {
        // 	g_form.addInfoMessage('hello 1')
        //     g_form.removeOption('outcome', 'Amend and CONF');
        // }

        // //7906 Eliminating Amend outcome if legacy status is UNEX

        if (g_scratchpad.trdLifeCycle == 'UNEX') {
            g_form.removeOption('outcome', 'Amend and CONF');
            g_form.removeOption('outcome', 'Amend Trade');
        }
		if (g_scratchpad.trdLifeCycle == 'PCON' && g_scratchpad.trdLifeCycleStatus == 'TradToBeMtchdNtrnly' ) {
            g_form.addOption('outcome', 'No Amendment Required');
        }
    });
}


function outcomesParse(response) {
    var outcomesArr = JSON.parse(response);
    for (var i = 0; i < outcomesArr.length; i++) {
        g_form.addOption('outcome', outcomesArr[i].value, outcomesArr[i].displayValue);
    }
}
